from pathlib import Path
import json
from docx import Document
from docx.shared import Pt
P=Path(__file__).parent
texts={
1:'지금부터 약이음에서 가족의 약 자료를 등록하고, 달라진 기록을 확인한 뒤 저장하는 과정을 보겠습니다.',
2:'먼저 자료를 등록할 가족을 선택합니다. 이후의 작업은 화면에 표시된 가족을 기준으로 진행합니다.\n\n사진 비교에서는 이전 자료와 현재 자료를 함께 준비합니다. 지금 사용하는 사진은 개인정보가 없는 합성 약봉투입니다. 새로 촬영한 장면에는 시연용 가상 응답을 사용합니다.\n\n두 사진을 선택하고 각각의 기준일을 확인합니다. 어느 시점의 자료인지 구분하기 위한 날짜입니다.\n\n준비를 마치면 사진 읽기를 진행합니다. 읽어 온 내용은 바로 확정되지 않습니다. 다음 화면에서 사용자가 원본과 대조하고, 필요한 내용을 수정합니다.',
3:'이제 사진과 읽어 온 내용을 확인합니다. 이전과 현재의 자료를 나란히 보면서 제품명과 투약 정보를 대조할 수 있습니다.\n\n먼저 원본 사진을 보겠습니다. 이전 사진에는 한 번에 한 정, 현재 사진에는 한 번에 두 정이라고 적혀 있습니다.\n\n현재 화면은 내용 대조를 보여 드리기 위한 가상 오류 사례입니다. 실제 제미나이에서 발생한 오류가 아닙니다. 원본에는 두 정이지만, 가상 추출값은 한 정으로 준비했습니다.\n\n사용자는 원본을 보고 다른 값을 두 정으로 수정합니다. 처음 읽어 온 값과 사용자가 수정한 내용은 구분해서 확인할 수 있습니다.\n\n알 수 없는 내용은 추측해서 채우지 않습니다. 확인이 어려운 값은 추가 확인이 필요한 상태로 남겨야 합니다.\n\n대조를 마치면 내용을 확인하고 비교를 진행합니다. 여기서 확인하는 것은 사진에 적힌 내용입니다. 실제로 약을 먹고 있는지는 뒤에서 따로 선택합니다.',
4:'비교 결과에서는 선택한 가족과 자료의 기준일을 먼저 확인합니다. 이어서 같은 기록과 달라진 기록의 수를 볼 수 있습니다.\n\n이번 사례에서는 변경된 기록이 한 건 있습니다. 약 카드에 이름과 변경 상태가 먼저 표시됩니다.\n\n강조된 부분을 보시면, 한 번에 한 정에서 두 정으로 달라졌습니다. 이전 값과 현재 값을 함께 보여 주기 때문에 바뀐 항목을 찾기 쉽습니다.',
5:'함량과 한 번에 먹는 양은 서로 다른 정보입니다. 이 사례에서는 함량이 같고, 한 번에 먹는 양이 달라졌습니다. 하루 횟수도 별도 항목으로 확인할 수 있습니다.\n\n자세한 내용이 필요하면 이전과 현재의 정보를 펼쳐 대조합니다. 성분과 함량, 투약량과 단위가 각각 표시됩니다.\n\n이 결과는 자료에 남은 기록의 차이입니다. 의학적 안전 판정이나 복용량 변경 권고가 아닙니다. 이전 자료에만 있는 기록도 복용 중단으로 판단하지 않습니다.',
6:'자료에 적힌 내용과 실제 복용 상태는 다를 수 있습니다. 약이음은 기록 비교만으로 복용 여부를 결정하지 않습니다.\n\n사용자는 지금 먹고 있는지, 먹지 않는지, 잘 모르겠는지를 따로 선택합니다. 아직 선택하지 않은 상태와 잘 모르겠다고 직접 답한 상태도 구분합니다.\n\n여기서는 먹고 있음을 선택한 뒤 결과를 저장하겠습니다.\n\n저장이 완료되면 완료 상태가 표시됩니다. 저장한 결과는 가족의 저장 기록에서 다시 열어 볼 수 있습니다.',
7:'사진 외에 건강보험심사평가원 자료 형식의 파일도 비교할 수 있습니다. 지금은 개인정보가 없는 가상 파일을 사용합니다.\n\n이전과 현재 파일을 선택한 뒤 기록 비교를 진행합니다. 파일을 선택하는 것만으로 외부 조회가 시작되지는 않습니다.\n\n결과는 사진과 같은 방식으로 확인합니다. 약 이름과 기록의 차이를 보고, 이전과 현재의 값을 대조합니다.\n\n여기에서도 실제 복용 상태는 따로 선택합니다. 비교 결과와 복용 상태를 저장한 뒤, 저장 기록에서 다시 열어 확인할 수 있습니다.',
8:'다음은 새로 촬영한 가상 화면과 구분되는 기존 실조회 확인 기록입니다.\n\n건강보험심사평가원 자료 경로에서는 단일 합성 제품의 실제 식약처 매칭부터 비교, 저장, 재조회까지 사용자 확인을 마쳤습니다.\n\n사진의 기존 검증은 실제 제미나이 추출과 가상 의약품 매칭입니다. 두 실제 서비스를 함께 사용한 사진 흐름까지 검증한 것은 아닙니다.',
9:'이번에는 비교에 필요한 정보가 확인되지 않는 자료입니다.\n\n성분이나 함량 같은 필수 정보가 불명확하면, 약이음은 값을 추측해 비교하지 않습니다. 추가 확인이 필요하다는 안내와 함께 비교를 보류합니다.\n\n비교 보류는 정상적으로 비교했지만 결과가 없는 상태와 다릅니다. 기록이 없거나 삭제됐다는 뜻도 아닙니다.\n\n화면에서 보류 사유를 확인할 수 있습니다. 확인 가능한 원본과 정리된 정보는 보존합니다.',
10:'저장 기록에서는 선택한 가족의 사진 자료와 건강보험심사평가원 자료를 구분해 볼 수 있습니다.\n\n먼저 사진 결과를 다시 열어 보겠습니다. 이전과 현재의 차이, 그리고 사용자가 선택한 복용 상태가 함께 표시됩니다.\n\n건강보험심사평가원 자료의 저장 결과도 같은 흐름으로 확인합니다. 두 종류의 자료가 서로 덮어쓰이지 않고 구분됩니다.\n\n다음은 브라우저를 휴대전화 크기로 설정한 화면입니다. 실제 휴대전화 촬영은 아니며, 작은 화면에서의 배치를 확인한 모습입니다.\n\n약 이름과 변경된 값, 저장한 복용 상태를 확인할 수 있습니다. 작은 화면에서도 기록 비교와 실제 복용 상태는 별도로 표시됩니다.',
11:'지금까지 자료 등록부터 내용 확인, 비교와 저장, 다시 보기까지 살펴봤습니다.\n\n기록의 차이는 쉽게 확인하고, 불명확한 정보는 보류합니다. 실제 복용 상태는 사용자가 따로 확인합니다.\n\n이어서 발표 자료에서 검증 범위와 남은 과제를 설명드리겠습니다.'}
plan=json.loads((P/'audio-plan.json').read_text());B=json.loads((P/'storyboard.json').read_text())
def ts(t):return f'{int(t//60):02}:{t%60:05.2f}'
lines=['# 약이음 TTS 최종 내레이션 대본','','사용자가 제공한 순서와 승인된 원문을 기준으로 합니다. 직접 청취한 전사본이 아닙니다. 4번 말미의 3번과 중복된 약 11.36초만 사용본에서 제외했고 원본 MP3는 보존했습니다. 발화 속도·음정 변경 없음.','']
for n,text in texts.items():
 spans=[x for x in plan['placements'] if x['file']==n];times=' / '.join(ts(x['timeline_start'])+'–'+ts(x['conservative_end']) for x in spans)
 lines+=[f'## {n}.mp3 — {times}',text,'']
(P/'내레이션_대본.md').write_text('\n'.join(lines))
doc=Document();doc.styles['Normal'].font.name='맑은 고딕';doc.styles['Normal'].font.size=Pt(11)
for line in lines:
 if line.startswith('# '):doc.add_heading(line[2:],0)
 elif line.startswith('## '):doc.add_heading(line[3:],2)
 elif line:doc.add_paragraph(line)
doc.save(P/'내레이션_대본.docx')
review=['# 문장·화면 대조 기록','','검토 방법: 승인된 원문 + 사용자 파일 순서 확인 + 로컬 Whisper 보조 전사 + 무음 구간 검출 + 실제 프레임 검토. 단어 단위 강제 정렬이나 직접 청취를 완료한 기록이 아닙니다. 로컬 전사는 오류가 있어 대본 원문을 대체하지 않았습니다.','','| 시간 | 해당 화면 | 겹치는 음성 파일 | 검토 기준 |','|---|---|---|---|']
for r in B:
 overlap=[x for x in plan['placements'] if x['timeline_start']<r['end'] and x['conservative_end']>r['start']]
 ids=', '.join(str(x['file']) for x in overlap) or '읽기·전환 무음'
 review.append(f"| {ts(r['start'])}–{ts(r['end'])} | {r['shot']} | {ids} | {r['caption'].replace(chr(10),' / ')} |")
review+=['','## 세부 연결 확인','- 가족 설명: 2번 시작 부분과 제목·선택 가족을 함께 표시하는 크롭. 제목은 원본 좌표 y≈100에 있고 크롭 y=80–330 안에 포함됩니다.','- 사진 읽기: 2번 후반의 준비·읽기 설명과 기존 실제 버튼 요청 장면.','- 수정 이유: 3번의 가상 오류 사례 및 원본 두 정/가상 한 정 설명과 같은 시점의 원본·입력값 대조.','- 수정 확인: 3번 후반과 사용자 수정 표시·명시적 대조 확인.','- 변경값: 4번 앞부분만 사용. 말미의 중복 설명은 3번 말미와 파형 상관 0.9554로 확인해 제외.','- 5번의 함량/투약량 설명 → 상세 비교 설명 → 의학적 판정 아님 설명을 각각 해당 카드·상세표·주의 문구에 배치. 두 문단 경계 무음에 4초/3초 읽기 시간을 삽입.','- 복용 상태 선택 → 저장 완료: 6번과 각각 미선택·선택·저장·완료 화면.','- 기존 실조회: 8번의 도입/실제 식약처/사진 검증/미검증 경계를 각각 전체 기록 카드와 해당 초점 카드에 연결. 신규 Mock을 실조회 화면으로 바꾸지 않음.','- 보류: 9번과 비교 미실행·사유·원본 보존을 보여 주는 기존 화면.','- 재조회·모바일: 10번 순서와 사진 → 자료 → 모바일 전체 → 카드 → 복용 상태.','- 11번 종료 뒤 약 1.7초를 두고 PPT 복귀. 모든 여유를 끝에 몰지 않음.','','발음·억양·실제 이어폰/PC 스피커 명료도·음악 구절의 주관적 자연스러움은 미검증입니다.']
(P/'문장_화면_대조표.md').write_text('\n'.join(review))
(P/'narration_texts.json').write_text(json.dumps(texts,ensure_ascii=False,indent=2))
print('narration and alignment records ready')
